/// <summary>
/// MPJ_34596_TransferOrderFinalisation, Data contract class for change route functionality
/// </summary>
[
     DataContractAttribute,
     SysOperationContractProcessingAttribute(classStr(MetTransferOrderShipmentWorkbenchRouteUpdateUIBuilder)),
     SysOperationGroupAttribute("ExistingRoute", "Existing route", "1", FormArrangeMethod::Vertical),
     SysOperationGroupAttribute("RouteChange","Route to change", "2")
    ]
class MetTransferOrderShipmentWorkbenchRouteUpdateContract implements SysOperationValidatable
{
    container            transferOrderList;
    METRouteStop         metRouteStop,metRouteStopChange;
    METRoute             metPrimaryRoute,metPrimaryRouteChange;

}

Method.Source:
    /// <summary>
    /// parm method for transfer order list container which contains transfer order 
    /// </summary>
    /// <param name = "_transferOrderList">transfer order list</param>
    /// <returns>transfer order list</returns>
    [DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
    public container parmTransferOrderList(container _transferOrderList = transferOrderList)
    {
        transferOrderList = _transferOrderList;

        return transferOrderList;
    }

    /// <summary>
    /// get/set existing primary route
    /// </summary>
    /// <param name = "_metPrimaryRoute">MetPrimaryRoute</param>
    /// <returns>METRoute</returns>
    [DataMemberAttribute('METRoute'),
     SysOperationGroupMemberAttribute("ExistingRoute"),
     SysOperationDisplayOrderAttribute("1"),
        SysOperationLabelAttribute(literalStr("@MET:PrimaryRoute"))]
    public METRoute parmPrimaryRoute(METRoute _metPrimaryRoute = metPrimaryRoute)
    {
        metPrimaryRoute = _metPrimaryRoute;

        return metPrimaryRoute;
    }

    /// <summary>
    /// Get/set exiting route stop
    /// </summary>
    /// <param name = "_metRouteStop">metRouteStop</param>
    /// <returns>METRouteStop</returns>
    [DataMemberAttribute('METRouteStop'),
     SysOperationGroupMemberAttribute("ExistingRoute"),
     SysOperationDisplayOrderAttribute("2")]
    public METRouteStop parmRouteStop(METRouteStop _metRouteStop = metRouteStop)
    {
        metRouteStop = _metRouteStop;

        return metRouteStop;
    }

    /// <summary>
    /// get/set change primary route
    /// </summary>
    /// <param name = "_metPrimaryRouteChange">metPrimaryRouteChange</param>
    /// <returns>METRoute</returns>
    [DataMemberAttribute('METRoute'),
     SysOperationGroupMemberAttribute("RouteChange"),
     SysOperationDisplayOrderAttribute("3"),
      SysOperationLabelAttribute(literalStr("@MET:ChangePrimarRouteTo"))]
    public METRoute parmPrimaryRouteChange(METRoute _metPrimaryRouteChange = metPrimaryRouteChange)
    {
        metPrimaryRouteChange = _metPrimaryRouteChange;

        return metPrimaryRouteChange;
    }

    /// <summary>
    /// get/set change route stop
    /// </summary>
    /// <param name = "_metRouteStopChange">metRouteStopChange</param>
    /// <returns>METRouteStop</returns>
    [DataMemberAttribute('METRouteStop'),
     SysOperationGroupMemberAttribute("RouteChange"),
     SysOperationDisplayOrderAttribute("4"),
     SysOperationLabelAttribute(literalStr("@MET:ChangeRouteStopTo"))]
    public METRouteStop parmRouteStopChange(METRouteStop _metRouteStopChange = metRouteStopChange)
    {
        metRouteStopChange = _metRouteStopChange;

        return metRouteStopChange;
    }

    /// <summary>
    /// validate parm
    /// </summary>
    /// <returns>boolean</returns>
    public boolean validate()
    {
        boolean isValid = true;

        if (!metRouteStopChange || !metPrimaryRouteChange)
        {

            isValid = checkFailed("@SYS37918");
        }


        return isValid;
    }
